import React, { createContext, useContext, useState, useEffect } from 'react';
import {
    onAuthStateChanged,
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    signOut
} from 'firebase/auth';
import { auth } from '../firebase/config';

const AuthContext = createContext();

export const useAuth = () => {
    return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
    const [currentUser, setCurrentUser] = useState(null);
    const [loading, setLoading] = useState(true);

    // Funcția de înregistrare (creează userul în Auth)
    // Rolul (adopter/shelter) este salvat separat în RegistrationPage.js
    function register(email, password) {
        return createUserWithEmailAndPassword(auth, email, password);
    }

    // Funcția de login
    function login(email, password) {
        return signInWithEmailAndPassword(auth, email, password);
    }

    // Funcția de logout
    function logout() {
        return signOut(auth);
    }

    // Monitorizează dacă userul este logat sau nu
    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (user) => {
            setCurrentUser(user);
            setLoading(false);
        });

        return unsubscribe;
    }, []);

    const value = {
        currentUser, // Am numit variabila currentUser pentru claritate
        login,
        register,
        logout
    };

    return (
        <AuthContext.Provider value={value}>
            {!loading && children}
        </AuthContext.Provider>
    );
};
